def memory_estimate(args, heads):
    """Approximate peak live device bytes, not a native workspace bound."""
    q, history, hidden, rank = args.queries, args.history, args.hidden, args.q_rank
    chunk = min(history, args.history_chunk)
    rows = max(q, chunk)
    weights = hidden * (rank + 576) + rank * heads * 192
    pages = max(1, (history + q + 127) // 128)
    components = {
        "processed_MX_projection_weights_and_scales": weights + weights // 32,
        "private_native_projection_copy": (weights + weights // 32)
        if "native" in args.frontend
        else 0,
        "model_UK_UV_and_private_expansion_weight_copies": heads
        * 512
        * (128 + 128)
        * 6,
        "persistent_FP8_cache_and_guards": pages * (128 * 576 + args.gap) + 512,
        "synthetic_hidden_and_history_inputs": 2 * (q * hidden + history * 576),
        "native_current_scratch_and_Q512_temporaries": (
            q * heads * 576 * 2 + ((q + 127) // 128) * 128 * 576 * 2
        )
        if "native" in args.frontend
        else 0,
        "projection_norm_and_MX_quant_temporaries": q
        * (hidden * 2 + rank * 8 + 576 * 8),
        "retained_correctness_outputs_and_main_buffers": q
        * heads
        * (512 * 2 + 4 + len(args.frontend) * (192 * 2 + 128 * 2 + 4))
        + len(args.frontend) * q * 576 * 2,
        "gather_cast_expanded_KV_and_FIA_input_copies": rows
        * (576 * 4 + heads * (256 + 192 + 128) * 2),
        "FP32_partial_outputs_and_LSE_merge_temporaries": q * heads * (128 * 4 + 4) * 5,
        "QFA_padding_MX_data_and_scale_temporaries": (
            q * heads * 256 * 4 + rows * heads * 256 * 8
        )
        if args.attention == "qfa"
        else 0,
        "runtime_workspace_placeholder": 512 * 1024**2,
    }
    return {
        "estimated_peak_mib": sum(components.values()) / 1024**2,
        "components_bytes": components,
        "caveat": "Rough live-tensor estimate; native/compiler workspace, fragmentation, allocator retention and other card users are unknown. This is not a reservation or hard cap. Independent reference also uses host RAM.",
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--card",
        type=int,
        default=0,
        help="physical A5 card; each worker sees logical 0",
    )
    parser.add_argument("--heads", type=int, nargs="+", default=[12, 24, 48])
    parser.add_argument(
        "--frontend",
        choices=("ordinary", "native"),
        nargs="+",
        default=["ordinary", "native"],
    )
    parser.add_argument("--attention", choices=("fia", "qfa"), default="fia")
    parser.add_argument("--queries", type=int, default=9)
    parser.add_argument("--history", type=int, default=129)
    parser.add_argument("--hidden", type=int, default=7168)
    parser.add_argument("--q-rank", type=int, default=1536)
    parser.add_argument("--history-chunk", type=int, default=4096)
    parser.add_argument("--gap", type=int, default=256)
    parser.add_argument("--reference-rows", type=int, default=9)
    parser.add_argument("--benchmark", action="store_true")
    parser.add_argument("--warmup", type=int, default=3)
    parser.add_argument("--iterations", type=int, default=10)
    parser.add_argument("--timeout", type=int, default=1200)
    parser.add_argument("--output-dir")
    parser.add_argument(
        "--plan", action="store_true", help="CPU-only inventory, no native imports"
    )
    parser.add_argument(
        "--show-license",
        action="store_true",
        help="Print complete license for the embedded official QFA CPU golden",
    )
    parser.add_argument("--worker", action="store_true", help=argparse.SUPPRESS)
    args = parser.parse_args()
    if args.show_license:
        print(CANN_NOTICE)  # noqa: F821 - generated source attribution
        print(CANN_LICENSE)  # noqa: F821 - generated complete license
        return 0
    if any(
        value <= 0
        for value in (
            args.queries,
            args.history_chunk,
            args.reference_rows,
            args.iterations,
        )
    ):
        parser.error(
            "queries, history-chunk, reference-rows and iterations must be positive"
        )
    if args.history < 0 or args.gap < 0 or args.gap % 32 or args.warmup < 1:
        parser.error(
            "history >=0, gap nonnegative and 32-byte aligned, warmup >=1 required"
        )
    if args.hidden not in (
        1024,
        2048,
        3072,
        4096,
        5120,
        6144,
        7168,
        7680,
        8192,
    ) or args.q_rank not in (1536, 2048):
        parser.error("geometry must satisfy CANN package NoPE MLA Prolog constraints")
    if not args.heads or any(not 1 <= value <= 128 for value in args.heads):
        parser.error("heads must be in [1,128]")
    for item in PAYLOAD.values():  # noqa: F821 - supplied by pinned bundle generator
        if hashlib.sha256(item["source"].encode()).hexdigest() != item["sha256"]:
            raise RuntimeError("Embedded candidate hash mismatch")
    inventory = {
        "event": "plan",
        "heads": args.heads,
        "queries": args.queries,
        "history": args.history,
        "hidden": args.hidden,
        "q_rank": args.q_rank,
        "benchmark": args.benchmark,
        "frontends": args.frontend,
        "attention": args.attention,
        "qfa_numeric_standard": "pinned v9.2.0 official P-quant-aware CPU golden + dtype-specific official 99.5% comparator",
        "memory_estimates": {
            str(heads): memory_estimate(args, heads) for heads in args.heads
        },
        "history_chunk": args.history_chunk,
        "core_hashes": {key: item["sha256"] for key, item in PAYLOAD.items()},  # noqa: F821 - generated payload
        "native_requires": "installed CANN 9.2.0 package mla_prolog NoPE/V4 wrapper and matching native runtime",
        "native_extra_work": "private UK=[I128|0] still computes 128->512 then takes Q128+raw64",
        "scope": "synthetic one-card eager; not model/graph/TP/DCP/HCCL acceptance",
    }
    if args.plan:
        print(json.dumps(inventory), flush=True)
        return 0
    if args.worker:
        if len(args.heads) != 1:
            parser.error("worker takes exactly one head count")
        args.heads = args.heads[0]
        os.environ["ASCEND_RT_VISIBLE_DEVICES"] = str(args.card)
        os.environ.pop("ASCEND_DEVICE_ID", None)
        # Isolate from the installed VA/plugin import tree and its import cycles.
        for name in (
            "vllm_ascend",
            "vllm_ascend.attention",
            "vllm_ascend.quantization",
            "vllm_ascend.quantization.methods",
            "vllm_ascend.quantization.methods.w8a8",
        ):
            package = types.ModuleType(name)
            package.__path__ = []
            sys.modules[name] = package
        modules = {}
        for key, item in PAYLOAD.items():  # noqa: F821 - generated payload
            module = types.ModuleType(item["module"])
            module.__file__ = "embedded_" + key + ".py"
            sys.modules[module.__name__] = module
            exec(compile(item["source"], module.__file__, "exec"), module.__dict__)  # noqa: S102 - exact pinned local payload
            modules[key] = module
        modules["worker"].run(args, modules)
        return 0
    directory = (
        Path(args.output_dir)
        if args.output_dir
        else Path(tempfile.mkdtemp(prefix="fia-expanded-", dir="/mnt"))
    )
    directory.mkdir(parents=True, exist_ok=True)
    (directory / "plan.json").write_text(json.dumps(inventory, indent=2) + "\n")
    results = []
    for heads in args.heads:
        log = directory / f"heads-{heads}.log"
        command = [
            sys.executable,
            "-u",
            str(Path(__file__).resolve()),
            "--worker",
            "--card",
            str(args.card),
            "--heads",
            str(heads),
            "--attention",
            args.attention,
            "--frontend",
            *args.frontend,
            "--queries",
            str(args.queries),
            "--history",
            str(args.history),
            "--hidden",
            str(args.hidden),
            "--q-rank",
            str(args.q_rank),
            "--history-chunk",
            str(args.history_chunk),
            "--gap",
            str(args.gap),
            "--reference-rows",
            str(args.reference_rows),
            "--warmup",
            str(args.warmup),
            "--iterations",
            str(args.iterations),
        ]
        if args.benchmark:
            command.append("--benchmark")
        print(
            json.dumps(
                {
                    "event": "begin",
                    "heads": heads,
                    "log": str(log),
                    "note": "native package host extension may load at first invocation",
                }
            ),
            flush=True,
        )
        timed_out = False
        with log.open("w") as stream:
            process = subprocess.Popen(
                command, stdout=stream, stderr=subprocess.STDOUT, start_new_session=True
            )
            try:
                code = process.wait(timeout=args.timeout)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
                code, timed_out = -1, True
        records = []
        for line in log.read_text(errors="replace").splitlines():
            try:
                record = json.loads(line)
                if isinstance(record, dict):
                    records.append(record)
            except json.JSONDecodeError:
                pass
        passed = code == 0 and any(
            record.get("event") == "suite_complete" and record.get("pass") is True
            for record in records
        )
        result = {
            "heads": heads,
            "pass": passed,
            "returncode": code,
            "timeout": timed_out,
            "log": str(log),
        }
        results.append(result)
        print(json.dumps({"event": "case_complete", **result}), flush=True)
        for record in records:
            if record.get("event") == "performance":
                print(json.dumps(record), flush=True)
        if not passed:
            print(
                "\n".join(log.read_text(errors="replace").splitlines()[-80:]),
                flush=True,
            )
            break
    success = len(results) == len(args.heads) and all(
        result["pass"] for result in results
    )
    summary = {
        "event": "summary",
        "all_passed": success,
        "results": results,
        "directory": str(directory),
        "scope": "synthetic ordinary/native expanded-FIA eager chains; no model/TP/DCP/graph acceptance",
    }
    (directory / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    print(json.dumps(summary), flush=True)
    return 0 if success else 1


if __name__ == "__main__":
    raise SystemExit(main())
